    <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=DM+Sans:wght@400;600;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --indigo: #4f46e5; --violet: #7c3aed;
            --surface: #ffffff; --surface-2: #f5f4ff;
            --border: #e5e3f5; --text-primary: #1e1b4b;
            --text-secondary: #6b7280; --text-muted: #9ca3af;
            --radius: 16px; --radius-sm: 9px;
            --shadow-lg: 0 12px 40px rgba(79,70,229,0.18), 0 4px 12px rgba(0,0,0,0.08);
            --shadow-drop: 0 8px 24px rgba(15,12,46,0.5);
        }
        * { margin:0; padding:0; box-sizing:border-box; }
        body {
            font-family:'DM Sans','Noto Sans JP',sans-serif;
            background:#0f0c2e; min-height:100vh;
            display:flex; flex-direction:column; align-items:center;
            padding:16px 14px 48px; position:relative; overflow-x:hidden;
        }
        body::before {
            content:''; position:fixed; inset:0;
            background:
                radial-gradient(ellipse 80% 60% at 15% 15%, rgba(79,70,229,0.38) 0%, transparent 60%),
                radial-gradient(ellipse 60% 50% at 85% 85%, rgba(124,58,237,0.32) 0%, transparent 60%),
                radial-gradient(ellipse 45% 40% at 65% 5%, rgba(99,102,241,0.22) 0%, transparent 55%);
            pointer-events:none; z-index:0;
        }
        body > * { position:relative; z-index:1; }

        /* ── Header bar ── */
        .top-bar {
            width:100%; max-width:720px;
            display:flex; align-items:center; justify-content:space-between;
            padding:0 2px; margin-bottom:10px;
        }

        .brand { display:flex; align-items:center; gap:10px; flex-shrink:0; }
        .brand-icon { width:38px; height:38px; border-radius:10px; box-shadow:0 2px 8px rgba(0,0,0,0.3); }
        .brand-name { font-weight:700; font-size:1.15rem; color:#fff; letter-spacing:-0.02em; }
        .brand-sub { font-size:0.63rem; color:rgba(255,255,255,0.48); font-weight:400; margin-top:1px; }

        /* Nav buttons */
        .nav-btns { display:flex; gap:6px; align-items:center; }

        .nav-btn {
            padding:7px 13px;
            background:rgba(255,255,255,0.09);
            border:1px solid rgba(255,255,255,0.15);
            border-radius:8px;
            color:rgba(255,255,255,0.75);
            font-family:inherit; font-size:0.73rem; font-weight:600;
            cursor:pointer; white-space:nowrap;
