        .nav-btn:hover {
            background:rgba(255,255,255,0.16);
            border-color:rgba(255,255,255,0.3);
            color:#fff;
        }
        .nav-btn.active {
            background:rgba(255,255,255,0.18);
            border-color:rgba(255,255,255,0.4);
            color:#fff;
        }

        /* ── Dropdown panel ── */
        .dropdown-wrap {
            width:100%; max-width:720px;
            overflow:hidden;
            max-height:0; opacity:0;
            transition:max-height 0.36s ease, opacity 0.28s ease, margin-bottom 0.36s ease;
            margin-bottom:0;
        }
        .dropdown-wrap.open {
            max-height:480px; opacity:1;
            margin-bottom:14px;
        }

        .dropdown-panel {
            display:none;
            background:var(--surface);
            border-radius:var(--radius);
            box-shadow:var(--shadow-lg);
            padding:20px 26px 22px;
        }
        .dropdown-panel.active { display:block; }

        /* Flash */
        .flash-messages { margin-bottom:12px; }
        .flash-message { padding:8px 12px; border-radius:var(--radius-sm); font-size:0.8rem; margin-bottom:6px; }
        .flash-message.error  { background:#fef2f2; color:#b91c1c; border:1px solid #fecaca; }
        .flash-message.success{ background:#f0fdf4; color:#15803d; border:1px solid #bbf7d0; }

        /* Collapsible rows (Google + email) */
        .fold-toggle {
            display:flex; align-items:center; gap:6px;
            width:100%; background:none; border:none; cursor:pointer;
            padding:8px 0 6px; font-family:inherit; font-size:0.76rem;
            color:var(--text-secondary); transition:color 0.18s;
            border-top:1px solid var(--border);
        }
        .fold-toggle:first-of-type { border-top:none; padding-top:0; }
        .fold-toggle:hover { color:var(--indigo); }
        .fold-toggle .arrow { margin-left:auto; font-size:0.6em; transition:transform 0.25s; }
        .fold-toggle.open .arrow { transform:rotate(180deg); }

        .fold-body { max-height:0; overflow:hidden; transition:max-height 0.32s ease, opacity 0.28s ease; opacity:0; }
        .fold-body.open { max-height:320px; opacity:1; }

        .google-btn {
            display:flex; align-items:center; justify-content:center;
            width:100%; padding:11px 14px; margin-top:8px;
            background:white; border:1.5px solid #e2e0f0;
            border-radius:var(--radius-sm); color:var(--text-primary);
            text-decoration:none; font-weight:600; font-size:0.86rem; gap:9px;
            transition:all 0.2s; box-shadow:0 1px 3px rgba(79,70,229,0.07);
