        input[type="email"],input[type="password"] { width:100%; padding:8px 10px; border:1.5px solid var(--border); border-radius:var(--radius-sm); font-family:inherit; font-size:0.84rem; color:var(--text-primary); background:white; transition:border-color 0.2s,box-shadow 0.2s; }
        input:focus { outline:none; border-color:#818cf8; box-shadow:0 0 0 3px rgba(99,102,241,0.1); }
        .login-btn { width:100%; margin-top:12px; padding:9px; background:linear-gradient(135deg,var(--indigo) 0%,var(--violet) 100%); color:white; border:none; border-radius:var(--radius-sm); font-family:inherit; font-weight:700; font-size:0.84rem; cursor:pointer; transition:opacity 0.2s,transform 0.2s; }
        .login-btn:hover { opacity:0.9; transform:translateY(-1px); }
