        .forgot-link:hover { color:var(--indigo); }

        /* Policy panel */
        .policy-list { list-style:none; }
        .policy-list li { border-bottom:1px solid var(--border); }
        .policy-list li:last-child { border-bottom:none; }
        .policy-list a { display:flex; align-items:center; justify-content:space-between; padding:11px 2px; color:var(--text-primary); text-decoration:none; font-size:0.84rem; font-weight:500; transition:color 0.18s; }
        .policy-list a:hover { color:var(--indigo); }
        .policy-list a::after { content:'›'; color:#818cf8; font-size:1.2em; font-weight:700; }

        /* About panel */
        .about-body { font-size:0.82rem; color:#555; line-height:1.75; }
        .about-body+.about-body { margin-top:10px; }
        .about-note { font-size:0.74rem; color:#999; margin-top:10px; }

        /* ── Guest apps ── */
        .guest-section { width:100%; max-width:720px; }
        .section-label { display:flex; align-items:center; gap:8px; color:rgba(255,255,255,0.6); font-size:0.7rem; font-weight:700; letter-spacing:0.09em; text-transform:uppercase; margin-bottom:12px; padding:0 2px; }
        .section-label::after { content:''; flex:1; height:1px; background:rgba(255,255,255,0.11); }

        .apps-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(180px,1fr)); gap:12px; }

        .app-card { background:rgba(255,255,255,0.08); backdrop-filter:blur(14px); -webkit-backdrop-filter:blur(14px); border:1px solid rgba(255,255,255,0.12); border-radius:var(--radius); padding:26px 16px 20px; text-decoration:none; display:flex; flex-direction:column; align-items:center; gap:8px; transition:background 0.2s,border-color 0.2s,transform 0.2s,box-shadow 0.2s; }
        .app-card:hover { background:rgba(255,255,255,0.14); border-color:rgba(255,255,255,0.28); transform:translateY(-3px); box-shadow:0 8px 28px rgba(0,0,0,0.25); }
        .app-emoji { font-size:2.2rem; line-height:1; filter:drop-shadow(0 2px 6px rgba(0,0,0,0.35)); }
        .app-name { font-size:0.84rem; font-weight:700; color:rgba(255,255,255,0.93); text-align:center; line-height:1.3; }
        .app-desc { font-size:0.68rem; color:rgba(255,255,255,0.42); text-align:center; line-height:1.4; }
        .ext-badge { font-size:0.56rem; font-weight:700; letter-spacing:0.05em; color:rgba(255,255,255,0.35); border:1px solid rgba(255,255,255,0.18); border-radius:4px; padding:1px 5px; margin-top:2px; }



        .footer-note { width:100%; max-width:720px; margin-top:22px; color:rgba(255,255,255,0.22); font-size:0.65rem; text-align:center; line-height:1.8; }

        /* ── Responsive ── */
        @media (max-width:520px) {
            body { padding:12px 10px 40px; }
            .nav-btn { padding:6px 9px; font-size:0.68rem; }
            .dropdown-panel { padding:16px 16px 18px; }
            .apps-grid { grid-template-columns:repeat(2,1fr); gap:9px; }
            .app-card { padding:20px 12px 16px; }
            .app-emoji { font-size:1.9rem; }
            .login-prompt { flex-direction:column; text-align:center; gap:9px; }
