        }

        /* Animations */
        .top-bar { animation:fadeUp 0.35s ease both; }
        .dropdown-wrap { animation:fadeUp 0.35s ease both 0.05s; }
        .guest-section { animation:fadeUp 0.4s ease both 0.08s; }
        @keyframes fadeUp { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }
    </style>
</head>
