                <div class="ext-badge">本サイト</div>
            </a>
            {% endif %}
            {% if config.get('SORAKARA_PUBLIC') %}
            <a class="app-card guest-link" href="{{ url_for('guest.go', app_id='sorakara') }}">
                <div class="app-emoji">🪂</div>
                <div class="app-name">そらから</div>
                <div class="app-desc">福知山の空をグライダーで遊覧飛行</div>
                <div class="ext-badge">本サイト</div>
            </a>
            {% endif %}
            <a class="app-card guest-link" href="{{ url_for('guest.go', app_id='free_hand_curve') }}">
                <div class="app-emoji">➿</div>
                <div class="app-name">フリーハンド曲線</div>
                <div class="app-desc">おたのしみ</div>
                <div class="ext-badge">本サイト</div>
            </a>

            <a class="app-card guest-link" href="{{ url_for('guest.go', app_id='ts_solvers') }}">
                <div class="app-emoji">😮‍💨</div>
                <div class="app-name">巡回セールスマン<br>問題ソルバー</div>
                <div class="app-desc">NP困難問題に挑戦！</div>
                <div class="ext-badge">本サイト</div>
            </a>

        </div>
    </div>
    <script>
    var currentPanel = null;
    var currentBtn   = null;

    function togglePanel(id, btn) {
        var wrap = document.getElementById('dropdownWrap');

        // 同じボタンを押したら閉じる
        if (currentPanel === id) {
            wrap.classList.remove('open');
            btn.classList.remove('active');
            currentPanel = null; currentBtn = null;
            return;
        }

        // 別パネルへ切り替え
        document.querySelectorAll('.dropdown-panel').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));

        document.getElementById('panel-' + id).classList.add('active');
        btn.classList.add('active');
        wrap.classList.add('open');
        currentPanel = id; currentBtn = btn;
    }

    function toggleFold(id) {
        var toggleBtn = document.getElementById(id + 'ToggleBtn');
        var body      = document.getElementById(id + 'Body');
        toggleBtn.classList.toggle('open');
        body.classList.toggle('open');
    }

    // ゲストリンクに画面解像度を付与
    document.querySelectorAll('.guest-link').forEach(function(a) {
        a.addEventListener('click', function() {
            var sc  = window.screen.width + 'x' + window.screen.height;
            var url = new URL(a.href, location.href);
            url.searchParams.set('screen', sc);
            a.href = url.toString();
        });
    });
    </script>
</body>
</html>

