        }
        input[type="text"] {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 1rem;
        }
        input:focus {
            outline: none;
            border-color: #667eea;
            box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
        }
        input:disabled {
            background: #f5f5f5;
            color: #666;
        }
        .submit-btn {
            width: 100%;
            padding: 12px;
            background: #667eea;
            color: white;
            border: none;
            border-radius: 6px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
        }
        .submit-btn:hover {
            background: #5568d3;
        }
        .flash-messages {
            margin-bottom: 20px;
        }
        .flash-message {
            padding: 12px;
            border-radius: 6px;
            margin-bottom: 10px;
        }
        .flash-message.error {
            background: #fee;
            color: #c33;
            border: 1px solid #fcc;
        }
    </style>
</head>
<body>
    <div class="register-container">
        <h1>外部登録申請</h1>
        <p class="subtitle">学外関係者用</p>

        {% with messages = get_flashed_messages(with_categories=true) %}
            {% if messages %}
                <div class="flash-messages">
                    {% for category, message in messages %}
                        <div class="flash-message {{ category }}">{{ message }}</div>
                    {% endfor %}
                </div>
            {% endif %}
        {% endwith %}

        <div class="warning-box">
            <strong>注意:</strong>
            外部の方の登録には管理者の承認が必要です。申請後、承認されるまでお待ちください。
        </div>

        <form method="POST">
            <div class="form-group">
                <label for="email">メールアドレス</label>
                <input type="text" id="email" value="{{ email }}" disabled>
            </div>

            <div class="form-group">
                <label for="full_name">氏名 *</label>
                <input type="text" id="full_name" name="full_name" required placeholder="例: 山田 花子">
            </div>

            <div class="form-group">
                <label for="affiliation">所属 *</label>
                <input type="text" id="affiliation" name="affiliation" required placeholder="例: 〇〇大学、△△株式会社">
            </div>

            <button type="submit" class="submit-btn">申請を送信</button>
        </form>
    </div>
</body>
</html>

